# Try: move each cell DOWN by v rows (wrapping around)
def move_down_by_value(grid):
    output = [[0]*24 for _ in range(16)]
    for r in range(16):
        for c in range(24):
            v = grid[r][c]
            if v != 0:
                nr = (r + v) % 16  # Wrap around
                output[nr][c] = v
    return output

